#!/usr/bin/env node
// Differential harness: runs the Python executable and the Node port with the
// same argv and reports any divergence in stdout, stderr or exit status.
// The program name legitimately differs, so it is normalised before comparing.
import { spawnSync } from 'node:child_process';

const PY = '/workspace/dataset/test5_executable';
const JS = ['/output/test5.mjs'];

function normalise(text) {
  return text.split('test5_executable').join('«PROG»').split('test5.mjs').join('«PROG»');
}

export function compare(argv, env = {}) {
  const options = { encoding: 'buffer', env: { ...process.env, ...env } };
  const py = spawnSync(PY, argv, options);
  const js = spawnSync(process.execPath, [...JS, ...argv], options);
  const result = {
    argv,
    env,
    ok: true,
    py: {
      stdout: py.stdout.toString('utf8'),
      stderr: py.stderr.toString('utf8'),
      status: py.status,
    },
    js: {
      stdout: js.stdout.toString('utf8'),
      stderr: js.stderr.toString('utf8'),
      status: js.status,
    },
  };
  result.ok =
    normalise(result.py.stdout) === normalise(result.js.stdout) &&
    normalise(result.py.stderr) === normalise(result.js.stderr) &&
    result.py.status === result.js.status;
  return result;
}

export function report(cases) {
  let failures = 0;
  for (const testCase of cases) {
    const argv = Array.isArray(testCase) ? testCase : testCase.argv;
    const env = Array.isArray(testCase) ? {} : (testCase.env ?? {});
    const result = compare(argv, env);
    if (!result.ok) {
      failures += 1;
      console.log('MISMATCH', JSON.stringify({ argv, env }));
      console.log('  py:', JSON.stringify(result.py));
      console.log('  js:', JSON.stringify(result.js));
    }
  }
  console.log(`${cases.length - failures}/${cases.length} matched`);
  return failures;
}

if (process.argv[1] && process.argv[1].endsWith('difftest.mjs') && process.argv.length > 2) {
  const result = compare(process.argv.slice(2));
  console.log(JSON.stringify(result, null, 2));
  process.exit(result.ok ? 0 : 1);
}

/**
 * Port of dataset/networkx/test5.py.
 *
 *   import argparse
 *   import networkx as nx
 *
 *   parser = argparse.ArgumentParser()
 *   parser.add_argument('--a', type=int, required=True)
 *   ... (--b, --c, --d, --e)
 *   args = parser.parse_args()
 *
 *   G = nx.DiGraph()
 *   G.add_edges_from([(args.a, args.b), (args.b, args.c), (args.c, args.d), (args.d, args.e)])
 *   print(nx.is_directed_acyclic_graph(G))
 *
 * Run it as: node test5.mjs --a 1 --b 2 --c 3 --d 4 --e 5
 */

import { ArgumentParser } from './lib/argparse/index.mjs';
import * as nx from './lib/networkx/index.mjs';
import { int, pyStr, SystemExit } from './lib/python/index.mjs';

function main() {
  const parser = new ArgumentParser();
  parser.add_argument('--a', { type: int, required: true });
  parser.add_argument('--b', { type: int, required: true });
  parser.add_argument('--c', { type: int, required: true });
  parser.add_argument('--d', { type: int, required: true });
  parser.add_argument('--e', { type: int, required: true });
  const args = parser.parse_args();

  const G = new nx.DiGraph();
  G.add_edges_from([
    [args.a, args.b],
    [args.b, args.c],
    [args.c, args.d],
    [args.d, args.e],
  ]);
  console.log(pyStr(nx.is_directed_acyclic_graph(G))); // 检查是否为有向无环图
}

try {
  main();
} catch (error) {
  // argparse leaves through SystemExit; anything else is a genuine crash.
  if (error instanceof SystemExit) process.exit(error.code);
  throw error;
}

/**
 * Node identity.
 *
 * Python graphs key their nodes by hash and equality, so `1`, `1.0` and `True`
 * are one and the same node while arbitrarily large integers stay distinct.
 * JavaScript has no single value type with those properties, so every node is
 * reduced to a canonical string: numeric values collapse across the Number and
 * BigInt divide, and everything else is tagged by type so that, say, the string
 * '1' can never be mistaken for the integer 1.
 */

/**
 * @param {unknown} value
 * @returns {string} a key equal for exactly those values Python considers the
 *   same dictionary key
 */
export function nodeKey(value) {
  switch (typeof value) {
    case 'bigint':
      return `i${value.toString()}`;
    case 'boolean':
      return value ? 'i1' : 'i0';
    case 'number':
      if (Number.isNaN(value)) return 'f:nan';
      if (!Number.isFinite(value)) return value > 0 ? 'f:inf' : 'f:-inf';
      // An integral double is the same node as the corresponding integer, which
      // is what makes G.add_edge(1, 2) and G.add_edge(1.0, 2) coincide.
      if (Number.isInteger(value)) return `i${BigInt(value).toString()}`;
      return `f${value}`;
    case 'string':
      return `s${value}`;
    case 'undefined':
      return 'None';
    case 'object': {
      if (value === null) return 'None';
      if (Array.isArray(value)) {
        // Length-prefixed so that nested keys cannot run together.
        const parts = value.map((item) => {
          const encoded = nodeKey(item);
          return `${encoded.length}:${encoded}`;
        });
        return `t${value.length}[${parts.join('')}]`;
      }
      return `o${objectIdentity(value)}`;
    }
    default:
      return `o${objectIdentity(value)}`;
  }
}

let nextIdentity = 1;
const identities = new WeakMap();

/** Objects without value semantics fall back to identity, as in CPython. */
function objectIdentity(value) {
  let identity = identities.get(value);
  if (identity === undefined) {
    identity = nextIdentity;
    nextIdentity += 1;
    identities.set(value, identity);
  }
  return identity;
}
/**
 * `networkx.Graph`: an undirected simple graph.
 *
 * Adjacency is kept the way NetworkX keeps it -- a mapping of node to a mapping
 * of neighbour to edge attributes -- with an extra table from canonical key back
 * to the node value the caller supplied, since the key is a string.
 */

import { NetworkXError } from '../exceptions.mjs';
import { nodeKey } from '../utils/hashing.mjs';

export class Graph {
  constructor() {
    /** @type {Map<string, object>} node key to node attributes */
    this._node = new Map();
    /** @type {Map<string, unknown>} node key to the value it was added as */
    this._nodeValue = new Map();
    /** @type {Map<string, Map<string, object>>} node key to neighbour keys */
    this._adj = new Map();
  }

  is_directed() {
    return false;
  }

  is_multigraph() {
    return false;
  }

  /** The canonical key for a node value; see `utils/hashing.mjs`. */
  key(value) {
    return nodeKey(value);
  }

  add_node(value, attributes = {}) {
    const key = this.key(value);
    if (!this._node.has(key)) {
      this._node.set(key, { ...attributes });
      this._nodeValue.set(key, value);
      this._adj.set(key, new Map());
      return;
    }
    Object.assign(this._node.get(key), attributes);
  }

  add_nodes_from(values) {
    for (const value of values) this.add_node(value);
  }

  has_node(value) {
    return this._node.has(this.key(value));
  }

  add_edge(source, target, attributes = {}) {
    this.add_node(source);
    this.add_node(target);
    const sourceKey = this.key(source);
    const targetKey = this.key(target);

    const existing = this._adj.get(sourceKey).get(targetKey) ?? {};
    Object.assign(existing, attributes);
    this._adj.get(sourceKey).set(targetKey, existing);
    this._adj.get(targetKey).set(sourceKey, existing);
  }

  /**
   * @param {Iterable<[unknown, unknown] | [unknown, unknown, object]>} edges
   */
  add_edges_from(edges) {
    for (const edge of edges) {
      if (edge.length === 2) {
        this.add_edge(edge[0], edge[1]);
      } else if (edge.length === 3) {
        this.add_edge(edge[0], edge[1], edge[2]);
      } else {
        throw new NetworkXError(`Edge tuple ${JSON.stringify(edge)} must be a 2-tuple or 3-tuple.`);
      }
    }
  }

  has_edge(source, target) {
    const neighbours = this._adj.get(this.key(source));
    return neighbours !== undefined && neighbours.has(this.key(target));
  }

  /** Node values, in insertion order. */
  nodes() {
    return [...this._nodeValue.values()];
  }

  number_of_nodes() {
    return this._node.size;
  }

  /** `[source, target]` pairs, each undirected edge reported once. */
  edges() {
    const seen = new Set();
    const result = [];
    for (const [sourceKey, neighbours] of this._adj) {
      for (const targetKey of neighbours.keys()) {
        const canonical = sourceKey <= targetKey ? `${sourceKey}�${targetKey}` : `${targetKey}�${sourceKey}`;
        if (seen.has(canonical)) continue;
        seen.add(canonical);
        result.push([this._nodeValue.get(sourceKey), this._nodeValue.get(targetKey)]);
      }
    }
    return result;
  }

  number_of_edges() {
    return this.edges().length;
  }

  _adjacencyOf(value) {
    const neighbours = this._adj.get(this.key(value));
    if (neighbours === undefined) {
      throw new NetworkXError(`The node ${String(value)} is not in the graph.`);
    }
    return neighbours;
  }

  /** Neighbour values of a node. */
  neighbors(value) {
    return [...this._adjacencyOf(value).keys()].map((key) => this._nodeValue.get(key));
  }

  degree(value) {
    const neighbours = this._adjacencyOf(value);
    // A self-loop contributes two to an undirected degree.
    return neighbours.size + (neighbours.has(this.key(value)) ? 1 : 0);
  }
}
/**
 * `networkx.DiGraph`: a directed simple graph.
 *
 * Successors and predecessors are stored separately so that in- and out-degrees
 * are both O(1), which is what Kahn's algorithm in `algorithms/dag.mjs` wants.
 */

import { Graph } from './graph.mjs';

export class DiGraph extends Graph {
  constructor() {
    super();
    /** Successors; aliased as `_adj` so inherited lookups follow edge direction. */
    this._succ = this._adj;
    /** @type {Map<string, Map<string, object>>} */
    this._pred = new Map();
  }

  is_directed() {
    return true;
  }

  add_node(value, attributes = {}) {
    const key = this.key(value);
    const isNew = !this._node.has(key);
    super.add_node(value, attributes);
    if (isNew) this._pred.set(key, new Map());
  }

  add_edge(source, target, attributes = {}) {
    this.add_node(source);
    this.add_node(target);
    const sourceKey = this.key(source);
    const targetKey = this.key(target);

    const existing = this._succ.get(sourceKey).get(targetKey) ?? {};
    Object.assign(existing, attributes);
    this._succ.get(sourceKey).set(targetKey, existing);
    this._pred.get(targetKey).set(sourceKey, existing);
  }

  has_edge(source, target) {
    const successors = this._succ.get(this.key(source));
    return successors !== undefined && successors.has(this.key(target));
  }

  /** Directed edges as `[source, target]` pairs, in insertion order. */
  edges() {
    const result = [];
    for (const [sourceKey, successors] of this._succ) {
      for (const targetKey of successors.keys()) {
        result.push([this._nodeValue.get(sourceKey), this._nodeValue.get(targetKey)]);
      }
    }
    return result;
  }

  successors(value) {
    return this.neighbors(value);
  }

  predecessors(value) {
    return [...this._predecessorsOf(value).keys()].map((key) => this._nodeValue.get(key));
  }

  _predecessorsOf(value) {
    const predecessors = this._pred.get(this.key(value));
    if (predecessors === undefined) {
      throw new Error(`The node ${String(value)} is not in the digraph.`);
    }
    return predecessors;
  }

  /** `[node, in-degree]` pairs for every node, in insertion order. */
  in_degree() {
    return [...this._nodeValue.entries()].map(([key, value]) => [value, this._pred.get(key).size]);
  }

  /** `[node, out-degree]` pairs for every node, in insertion order. */
  out_degree() {
    return [...this._nodeValue.entries()].map(([key, value]) => [value, this._succ.get(key).size]);
  }

  degree(value) {
    return this._adjacencyOf(value).size + this._predecessorsOf(value).size;
  }
}
/**
 * Directed acyclic graph algorithms.
 *
 * The acyclicity test is the one NetworkX uses: attempt a topological ordering
 * with Kahn's algorithm and see whether every node comes out. Anything left over
 * still has an unsatisfied predecessor, which can only happen inside a cycle --
 * and a self-loop counts, since a node is then its own unsatisfied predecessor.
 */

import { NetworkXError, NetworkXUnfeasible } from '../exceptions.mjs';

/**
 * Nodes grouped into layers: every node in a generation depends only on nodes in
 * earlier ones.
 *
 * @param {import('../classes/digraph.mjs').DiGraph} G
 * @yields {unknown[]} one generation of node values
 */
export function* topological_generations(G) {
  if (!G.is_directed()) {
    throw new NetworkXError('Topological sort not defined on undirected graphs.');
  }

  const remainingInDegree = new Map();
  let zeroInDegree = [];
  for (const [node, degree] of G.in_degree()) {
    if (degree > 0) remainingInDegree.set(G.key(node), degree);
    else zeroInDegree.push(node);
  }

  while (zeroInDegree.length > 0) {
    const generation = zeroInDegree;
    zeroInDegree = [];
    for (const node of generation) {
      for (const child of G.neighbors(node)) {
        const childKey = G.key(child);
        const remaining = remainingInDegree.get(childKey) - 1;
        remainingInDegree.set(childKey, remaining);
        if (remaining === 0) {
          zeroInDegree.push(child);
          remainingInDegree.delete(childKey);
        }
      }
    }
    yield generation;
  }

  if (remainingInDegree.size > 0) {
    throw new NetworkXUnfeasible(
      'Graph contains a cycle or graph changed during iteration',
    );
  }
}

/**
 * A topological ordering of the nodes.
 *
 * @param {import('../classes/digraph.mjs').DiGraph} G
 * @yields {unknown} node values, dependencies first
 */
export function* topological_sort(G) {
  for (const generation of topological_generations(G)) {
    yield* generation;
  }
}

/**
 * Whether `G` is a directed acyclic graph. Undirected graphs are never one, and
 * a graph with no nodes vacuously is.
 *
 * @param {import('../classes/graph.mjs').Graph} G
 * @returns {boolean}
 */
export function is_directed_acyclic_graph(G) {
  if (!G.is_directed()) return false;
  try {
    // eslint-disable-next-line no-unused-vars
    for (const node of topological_sort(G)) {
      // Drained purely for its side effect of completing the ordering.
    }
    return true;
  } catch (error) {
    if (error instanceof NetworkXUnfeasible) return false;
    throw error;
  }
}

/**
 * `int(str)` with base 10, following CPython's two-step conversion.
 *
 * Results are returned as BigInt because Python integers are unbounded: the
 * graph in this port uses the parsed values as node identities, so collapsing
 * them onto IEEE-754 doubles would merge distinct nodes such as
 * 99999999999999999999998 and 99999999999999999999999.
 */

import { decimalValue, isAsciiSpace, isNonAsciiSpace } from './unicode.mjs';
import { PyValueError } from './errors.mjs';

/**
 * `_PyUnicode_TransformDecimalAndSpaceToASCII`.
 *
 * ASCII code points are passed through untouched, other whitespace collapses to
 * a plain space, other decimal digits become their ASCII counterpart, and
 * anything else becomes '?' so the scanner below rejects it.
 */
function transformDecimalAndSpaceToAscii(text) {
  let out = '';
  for (const character of text) {
    const codePoint = character.codePointAt(0);
    if (codePoint < 127) {
      out += character;
    } else if (isNonAsciiSpace(codePoint)) {
      out += ' ';
    } else {
      const digit = decimalValue(codePoint);
      out += digit < 0 ? '?' : String(digit);
    }
