 * The callable handed to `parser.add_argument(..., type=int)`. `typeName` stands
 * in for Python's `int.__name__`, which argparse interpolates into its
 * "invalid int value" diagnostic.
 */
export const int = (text) => pyInt(text);
int.typeName = 'int';

/**
 * The `networkx` namespace, mirroring the names the Python module exposes at top
 * level so that call sites read the same in both languages.
 */

export { Graph } from './classes/graph.mjs';
export { DiGraph } from './classes/digraph.mjs';
export {
  is_directed_acyclic_graph,
  topological_generations,
  topological_sort,
} from './algorithms/dag.mjs';
export {
  NetworkXError,
  NetworkXException,
  NetworkXNotImplemented,
  NetworkXUnfeasible,
} from './exceptions.mjs';
/**
 * The NetworkX exception hierarchy, as far as the ported algorithms need it.
 */

export class NetworkXException extends Error {
  constructor(message) {
    super(message);
    this.name = this.constructor.name;
  }
}

/** A misuse of the library, e.g. a topological sort of an undirected graph. */
export class NetworkXError extends NetworkXException {}

/**
 * The requested result cannot exist for this input -- raised when a topological
 * ordering is asked of a graph that contains a cycle.
 */
export class NetworkXUnfeasible extends NetworkXError {}

/** The algorithm is not defined for this class of graph. */
export class NetworkXNotImplemented extends NetworkXException {}
