#!/usr/bin/env node
// Differential fuzz of the GRAPH SEMANTICS surface of the test5 port.
//
// Shardable: SHARD=<i> NSHARDS=<n> node /tmp/fuzz_graphsem.mjs
// (the reference executable costs ~2s per run, so shards are run in parallel)

import { report } from '/tmp/difftest.mjs';

const cases = [];
const seen = new Set();

function addTuple(t) {
  const argv = ['--a', String(t[0]), '--b', String(t[1]), '--c', String(t[2]),
                '--d', String(t[3]), '--e', String(t[4])];
  const key = argv.join('�');
  if (seen.has(key)) return;
  seen.add(key);
  cases.push(argv);
}

// ---------------------------------------------------------------------------
// 1. Exhaustive: every 5-tuple over {0,1,2} -> 243 cases.
//    Covers all self-loop / duplicate-edge / cycle shapes on 3 labels,
//    including the node label 0 (falsy in JS).
// ---------------------------------------------------------------------------
function exhaustive(alphabet) {
  const n = alphabet.length;
  const total = n ** 5;
  for (let i = 0; i < total; i++) {
    let x = i;
    const t = [];
    for (let k = 0; k < 5; k++) { t.push(alphabet[x % n]); x = Math.floor(x / n); }
    addTuple(t);
  }
}
exhaustive([0, 1, 2]);

// ---------------------------------------------------------------------------
// 2. Exhaustive: every 5-tuple over {1,2,3,4} -> 1024 cases.
// ---------------------------------------------------------------------------
exhaustive([1, 2, 3, 4]);

// ---------------------------------------------------------------------------
// 3. Deterministic PRNG for the randomised families.
// ---------------------------------------------------------------------------
let state = 0x2f6e2b1n;
function rnd() { // 32-bit xorshift-ish LCG on BigInt, returns Number in [0,1)
  state = (state * 6364136223846793005n + 1442695040888963407n) & 0xffffffffffffffffn;
  return Number((state >> 11n) & 0x1fffffffffffffn) / 9007199254740992;
}
function pick(arr) { return arr[Math.floor(rnd() * arr.length)]; }

// ---------------------------------------------------------------------------
// 4. Randomised large values / negatives / mixed sign / zeros, drawn from a
//    small alphabet each time so cycles and repeats actually occur.
// ---------------------------------------------------------------------------
const poolFamilies = [
  // negatives only
  [-1, -2, -3],
  // mixed sign around zero
  [-1, 0, 1],
  [-2, -1, 0, 1, 2],
  // zeros and one other
  [0, 7],
  ['-0', '0', '+0'],            // three spellings of the same node
  ['1', '+1', '01', '0001'],    // four spellings of the same node
  // moderate large values
  [1000000, 1000001, -1000000],
  [2147483647, -2147483648, 2147483646],
  // 2**53 boundary
  [9007199254740992, 9007199254740993, 9007199254740991],
  ['9007199254740992', '9007199254740993'],
  // beyond 2**53: differ only in the last digit
  ['99999999999999999999998', '99999999999999999999999'],
  ['12345678901234567890123', '12345678901234567890124', '12345678901234567890125'],
  ['-99999999999999999999998', '-99999999999999999999999'],
  // 2**63 / 2**64 boundaries
  ['9223372036854775807', '9223372036854775808', '18446744073709551615', '18446744073709551616'],
  // absurdly huge, differing in the last digit only
  ['1' + '0'.repeat(60), '1' + '0'.repeat(59) + '1'],
  ['1'.repeat(80), '1'.repeat(79) + '2'],
];
for (const pool of poolFamilies) {
  for (let i = 0; i < 40; i++) {
    addTuple([pick(pool), pick(pool), pick(pool), pick(pool), pick(pool)]);
  }
}

// A wide random pool: mostly distinct values (DAG), occasionally repeating.
for (let i = 0; i < 120; i++) {
  const t = [];
  for (let k = 0; k < 5; k++) {
    if (t.length && rnd() < 0.45) t.push(t[Math.floor(rnd() * t.length)]);
    else t.push(Math.floor(rnd() * 2000000000) - 1000000000);
  }
  addTuple(t);
}

// Random huge-integer pool: values sharing long prefixes so any float
// round-trip would collapse them into one node.
for (let i = 0; i < 120; i++) {
  const base = '7' + '3'.repeat(20 + Math.floor(rnd() * 10));
  const pool = [];
  for (let d = 0; d < 4; d++) pool.push((rnd() < 0.5 ? '' : '-') + base.slice(0, -1) + d);
  const t = [];
  for (let k = 0; k < 5; k++) {
    if (t.length && rnd() < 0.5) t.push(t[Math.floor(rnd() * t.length)]);
    else t.push(pick(pool));
  }
  addTuple(t);
}

// ---------------------------------------------------------------------------
// 5. Hand-built shapes that pin down specific graph semantics.
// ---------------------------------------------------------------------------
const handBuilt = [
  [1, 2, 3, 4, 5],                       // plain path: DAG
  [1, 1, 1, 1, 1],                       // pure self-loop
  [1, 2, 1, 2, 1],                       // 2-cycle, duplicate edges
  [1, 2, 3, 1, 2],                       // 3-cycle plus re-entry
  [5, 4, 3, 2, 1],                       // descending path: DAG
  [0, 0, 0, 0, 0],                       // self-loop on falsy node 0
  [0, 1, 2, 3, 0],                       // cycle back through 0
  [1, 2, 3, 4, 1],                       // 4-cycle
  [1, 2, 3, 4, 2],                       // cycle not containing the source
  [1, 2, 3, 4, 3],
  [1, 2, 3, 4, 4],                       // self-loop at the tail only
  [1, 2, 2, 3, 4],                       // self-loop in the middle
  ['-0', '0', '1', '2', '3'],            // -0 and 0 must be one node
  ['0', '-0', '0', '-0', '0'],
  ['1', '1.0'],                          // (invalid, see below)
  // huge integers that differ only in the last digit -> must stay 2 nodes,
  // so a->b->a is a 2-cycle, not a self-loop
  ['99999999999999999999998', '99999999999999999999999',
   '99999999999999999999998', '99999999999999999999999', '99999999999999999999998'],
  // ... and the same pair used as a path -> DAG
  ['99999999999999999999998', '99999999999999999999999',
   '100000000000000000000000', '100000000000000000000001', '100000000000000000000002'],
  // all five huge and equal -> self-loop
  ['99999999999999999999999', '99999999999999999999999', '99999999999999999999999',
   '99999999999999999999999', '99999999999999999999999'],
  // 2**53 neighbours: 9007199254740993 is not representable as a double
  ['9007199254740992', '9007199254740993', '9007199254740992',
   '9007199254740993', '9007199254740992'],
  ['9007199254740993', '9007199254740994', '9007199254740995',
   '9007199254740996', '9007199254740997'],
  // 2**64 neighbours
  ['18446744073709551616', '18446744073709551617', '18446744073709551616',
   '18446744073709551617', '18446744073709551616'],
  // underscores and signs: same node written differently
  ['1_000', '1000', '+1000', '1_0_0_0', '01000'],
  // whitespace-padded spellings of the same node
  [' 1 ', '1', '\t1\n', '+1', '1'],
  // large negative self-loop
  ['-99999999999999999999999', '-99999999999999999999999', '1', '2', '3'],
  // sign flip only
  ['99999999999999999999999', '-99999999999999999999999',
   '99999999999999999999999', '-99999999999999999999999', '99999999999999999999999'],
];
for (const t of handBuilt) {
  if (t.length === 5) addTuple(t);
}
// the deliberately invalid one, kept as a raw argv
cases.push(['--a', '1', '--b', '1.0', '--c', '2', '--d', '3', '--e', '4']);

// ---------------------------------------------------------------------------
// Shard and run.
// ---------------------------------------------------------------------------
const nshards = Number(process.env.NSHARDS ?? 1);
const shard = Number(process.env.SHARD ?? 0);
const mine = cases.filter((_, i) => i % nshards === shard);
if (process.env.COUNT_ONLY) {
  console.log(`total ${cases.length} shard ${shard}/${nshards} -> ${mine.length}`);
  process.exit(0);
}
const failures = report(mine);
process.exit(failures ? 1 : 0);
